   180                  /* Quote: end of string */
   181                  if (c == '\"') {
   182                          if (tokens == NULL) {
   183                                  return 0;
   184                          }
   185                          token = jsmn_alloc_token(parser, tokens, num_tokens);
   186                          if (token == NULL) {
   187                                  parser->pos = start;
   188                                  return JSMN_ERROR_NOMEM;
   189                          }
   190                          jsmn_fill_token(token, JSMN_STRING, start+1, parser->pos);
   191  #ifdef JSMN_PARENT_LINKS
   192                          token->parent = parser->toksuper;
