   203                                  case '\"': case '/' : case '\\' : case 'b' :
   204                                  case 'f' : case 'r' : case 'n'  : case 't' :
   205                                          break;
   206                                  /* Allows escaped symbol \uXXXX */
   207                                  case 'u':
   208                                          parser->pos++;
