   210                                                  /* If it isn't a hex character we have an error */
   211                                                  if(!((js[parser->pos] >= 48 && js[parser->pos] <= 57) || /* 0-9 */
   212                                                                          (js[parser->pos] >= 65 && js[parser->pos] <= 70) || /* A-F */
   213                                                                          (js[parser->pos] >= 97 && js[parser->pos] <= 102))) { /* a-f */
   214                                                          parser->pos = start;
   215                                                          return JSMN_ERROR_INVAL;
   216                                                  }
   217                                                  parser->pos++;
   218                                          }
