   240          int count = parser->toknext;
   241
   242          for (; parser->pos < len && js[parser->pos] != '\0'; parser->pos++) {
   243                  char c;
   244                  jsmntype_t type;
   245
   246                  c = js[parser->pos];
   247                  switch (c) {
   248                          case '{': case '[':
   249  #ifdef JSMN_STRICT
   250                                  parser->toktype = (c == '{') ?
   251                                          JSMN_TOK_OPENING_BRACE : JSMN_TOK_OPENING_BRACKET;
   252  #endif
   253                                  count++;
   254                                  if (tokens == NULL) {
   255                                          break;
   256                                  }
   257                                  token = jsmn_alloc_token(parser, tokens, num_tokens);
   258                                  if (token == NULL)
   259                                          return JSMN_ERROR_NOMEM;
   260                                  if (parser->toksuper != -1) {
   261                                          tokens[parser->toksuper].size++;
   262  #ifdef JSMN_PARENT_LINKS
   263                                          token->parent = parser->toksuper;
   264  #endif
   265                                  }
   266                                  token->type = (c == '{' ? JSMN_OBJECT : JSMN_ARRAY);
   267                                  token->start = parser->pos;
   268                                  parser->toksuper = parser->toknext - 1;
   269                                  break;
   270                          case '}': case ']':
   271  #ifdef JSMN_STRICT
   272                                  if (tokens != NULL) {
   273                                          if (c == '}') {
   274                                                  if (jsmn_tok_expected
   275                                                      (parser->toktype, closing_brace_expected)) {
   276                                                          return JSMN_ERROR_INVAL;
   277                                                  }
   278                                          } else if (jsmn_tok_expected
   279                                                     (parser->toktype, closing_bracket_expected )) {
   280                                                  return JSMN_ERROR_INVAL;
   281                                          }
   282                                  }
   283                                  parser->toktype = (c == '}') ?
   284                                          JSMN_TOK_CLOSING_BRACE : JSMN_TOK_CLOSING_BRACKET;
   285  #endif
   286                                  if (tokens == NULL)
   287                                          break;
   288                                  type = (c == '}' ? JSMN_OBJECT : JSMN_ARRAY);
   289  #ifdef JSMN_PARENT_LINKS
   290                                  if (parser->toknext < 1) {
   291                                          return JSMN_ERROR_INVAL;
   292                                  }
   293                                  token = &tokens[parser->toknext - 1];
   294                                  for (;;) {
   295                                          if (token->start != -1 && token->end == -1) {
   296                                                  if (token->type != type) {
   297                                                          return JSMN_ERROR_INVAL;
   298                                                  }
   299                                                  token->end = parser->pos + 1;
   300                                                  parser->toksuper = token->parent;
   301                                                  break;
   302                                          }
   303                                          if (token->parent == -1) {
   304                                                  if(token->type != type || parser->toksuper == -1) {
   305                                                          return JSMN_ERROR_INVAL;
   306                                                  }
   307                                                  break;
   308                                          }
   309                                          token = &tokens[token->parent];
   310                                  }
   311  #else
   312                                  for (i = parser->toknext - 1; i >= 0; i--) {
   313                                          token = &tokens[i];
   314                                          if (token->start != -1 && token->end == -1) {
